const CHATGPT_SOURCE = { label: "OpenAI’s custom MCP server instructions", href: "https://developers.openai.com/api/docs/guides/custom-mcp-server" };
const CODE_SOURCE = { label: "Claude Code HTTP MCP configuration", href: "https://code.claude.com/docs/en/mcp" };
const CLAUDE_COMMAND = 'claude mcp add --transport http meadow https://findmeadow.com/mcp \\\n  --header "Authorization: Bearer $MEADOW_API_KEY"';
const makePage = page => ({ kind: "agent-api", preview: "agent", action: "Try for free", secondary: { label: "Read setup guide", href: "#workflow" }, ...page, faqs: [...page.faqs, ...SHARED_FAQS] });
const snippet = value => JSON.stringify(value, null, 2);
const videoPost = (account, settings, format = "video") => ({
  caption: "A look inside our studio.", title: "Inside Meadow Studio", format,
  mediaIds: ["UPLOADED_VIDEO_ID"], accountIds: [account],
  overrides: { [account]: { settings } },
  schedule: { mode: "scheduled", localDateTime: "2030-01-08T09:00", timeZone: "Africa/Douala" },
});
const restExample = (item, requestId) => `const base = "https://findmeadow.com/api/bridge";
const projectId = "YOUR_PROJECT_ID";
const headers = {
  Authorization: \`Bearer \${process.env.MEADOW_API_KEY}\`,
  "Content-Type": "application/json"
};
const payload = ${snippet({ requestId, items: [item] })};

// Run on your server after uploading media and reviewing these choices.
const previewResponse = await fetch(\`\${base}/projects/\${projectId}/posts/preview\`, {
  method: "POST", headers, body: JSON.stringify({ items: payload.items })
});
if (!previewResponse.ok) throw new Error(await previewResponse.text());
const preview = await previewResponse.json();
if (!preview.valid) throw new Error(JSON.stringify(preview.rows));

// Submit only after the content, accounts, time and settings are approved.
const response = await fetch(\`\${base}/projects/\${projectId}/posts\`, {
  method: "POST", headers, body: JSON.stringify(payload)
});
if (!response.ok) throw new Error(await response.text());
console.log(await response.json()); // Queued; check each delivery next.`;
const RESULT_FAQ = { q: "Does a successful tool call mean my post is live?", a: "No. A publish call submits the post to Meadow’s delivery queue. Use get_post in MCP, the REST post endpoint, or the dashboard to inspect every destination. A published status confirms delivery; TikTok inbox transfers use awaiting_publish and still need you to finish inside TikTok." };

