    code: restExample(videoPost("TIKTOK_ACCOUNT_ID", { privacy: "USER_SELECTED_ALLOWED_PRIVACY", consent: true }), "tiktok-studio-20300108"), codeLabel: "Example TikTok REST preview and submission", codeNote: "The privacy placeholder must be replaced with the user’s choice from the returned account options. consent: true is valid only after their Music Usage Confirmation. This example must not be used to choose or imply consent for them.",
    details: [{ title: "Connect and identify the account", text: "Complete TikTok authorization in Meadow and read the project’s accounts. Use the intended account ID for publishing; each connected account has its own permissions and available options." }, { title: "Read current creator choices", text: "Fetch the account options before showing the privacy and interaction controls. Only offer the returned choices, and respect disabled comments, duet, or stitch settings and available posting allowances." }, { title: "Choose direct or inbox delivery", text: "Direct posts require privacy and the user’s Music Usage Confirmation. Inbox uploads use deliveryMode: inbox with uploadConsent: true after confirmation, and leave the final publishing action to the user in TikTok." }, { title: "Track processing and outcome", text: "Queueing a video begins an asynchronous flow. Read the post’s TikTok delivery status until the outcome is known. Inbox completion is awaiting_publish, while a direct published result confirms the post went live." }],
    guide: [{ title: "Put consent in the application flow", text: "Your interface should show the TikTok account, the content to be posted, current privacy options, and the relevant confirmation before submitting. Ask for choices rather than supplying a default on the user’s behalf. preview validates the final settings; it does not replace the consent interaction." }, { title: "Use a cover suited to the delivery mode", text: "For a supported direct video post, the per-account settings can name an uploaded custom cover with thumbnailMediaId, or a video frame with videoCover containing mediaId and timestampMs. TikTok inbox uploads are finished inside TikTok and do not use Meadow’s direct-post cover selection." }],
